const fs = require('fs');
const path = require('path');

const blogPath = path.join(__dirname, '..', 'src', 'Blog.js');
let source = fs.readFileSync(blogPath, 'utf8');

// react-scripts 5 / its Babel parser can fail on optional chaining in this project.
// Normalize the patterns generated by the blog repair scripts before compilation.
const before = source;
source = source.replace(/article\?\.slug\s*\|\|\s*(['"])(.*?)\1/g, '(article && article.slug) || $1$2$1');
source = source.replace(/\?\./g, '.');

if (source !== before) {
  fs.writeFileSync(blogPath, source, 'utf8');
  console.log('[blog compatibility] normalized optional chaining in Blog.js');
} else {
  console.log('[blog compatibility] no optional chaining replacement needed');
}
